import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2024-01-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 1);

  const line = result.value.lines[0];
  assert.equal(line.sku, 'DES-HOUR');
  assert.equal(line.name, 'Design work (hour)');
  assert.equal(line.qty, 10);
  assert.equal(line.unitPrice, 8500);
  assert.equal(line.vatRate, 21);
});

test('createInvoice accepts multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-02-20',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 8 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
});

test('createInvoice reports CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for malformed date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '15/01/2024',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-1-15',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-35',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports DATE_INVALID for impossible dates', () => {
  // February 30th doesn't exist
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  // April only has 30 days
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-04-31',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice accepts valid dates including leap year dates', () => {
  // 2024 is a leap year, Feb 29 exists
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-29',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, true);

  // 2023 is not a leap year, Feb 28 exists
  const result2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-02-28',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(result2.ok, true);
});

test('createInvoice reports NO_LINES for empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports NO_LINES when lines is not an array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: undefined,
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports QTY_INVALID for zero quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports QTY_INVALID for negative quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports QTY_INVALID for non-integer quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty: 2.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports UNKNOWN_SKU for unknown product', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'FAKE-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice returns copies, not references', () => {
  const inputLines = [{ sku: 'DES-HOUR', qty: 1 }];
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: inputLines,
  });

  // Mutate the returned line
  result.value.lines[0].qty = 999;

  // Original should be unchanged
  assert.equal(inputLines[0].qty, 1);
});

test('createInvoice does not mutate input array', () => {
  const inputLines = [{ sku: 'DES-HOUR', qty: 1 }];
  createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: inputLines,
  });

  // Input should be unchanged
  assert.equal(inputLines[0].qty, 1);
  assert.equal(Object.keys(inputLines[0]).length, 2);
});

test('createInvoice works with various VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'PRINT-A4', qty: 100 }, // 9% VAT
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT (exempt)
      { sku: 'DES-HOUR', qty: 5 }, // 21% VAT
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 9);
  assert.equal(result.value.lines[1].vatRate, 0);
  assert.equal(result.value.lines[2].vatRate, 21);
});

test('lineTotal calculates qty × unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
});

test('lineTotal returns 0 for zero quantity', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 8500 }), 0);
});

test('lineTotal works with different unit prices', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 1 }), 5);
  assert.equal(lineTotal({ qty: 1, unitPrice: 1 }), 1);
  assert.equal(lineTotal({ qty: 1000, unitPrice: 10000 }), 10000000);
});

test('invoiceTotals sums line totals for single line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 85000);
});

test('invoiceTotals sums line totals for multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 0 }, // 85000
      { qty: 5, unitPrice: 9500, discountPercent: 0 }, // 47500
      { qty: 1, unitPrice: 120000, discountPercent: 0 }, // 120000
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 252500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 252500);
});

test('invoiceTotals returns 0 for empty invoice', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals returns a new object', () => {
  const invoice = { lines: [{ qty: 5, unitPrice: 1000 }] };
  const totals1 = invoiceTotals(invoice);
  const totals2 = invoiceTotals(invoice);
  assert.notEqual(totals1, totals2);
  assert.deepEqual(totals1, totals2);
});

test('invoiceTotals with real invoice from createInvoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });

  const totals = invoiceTotals(invoiceResult.value);
  // C-001 is gold tier, so lines get 5% discount
  // DES-HOUR: 10 * 8500 = 85000, discount 5% = 4250
  // DEV-HOUR: 5 * 9500 = 47500, discount 5% = 2375
  // Total discount: 6625
  // Total: 132500 - 6625 = 125875
  assert.equal(totals.subtotal, 132500);
  assert.equal(totals.discount, 6625);
  assert.equal(totals.total, 125875);
});

test('lineTotal returns integer cents', () => {
  const line = lineTotal({ qty: 3, unitPrice: 1010 });
  assert.ok(Number.isInteger(line));
  assert.equal(line, 3030);
});

test('invoiceTotals returns integer cents', () => {
  const invoice = {
    lines: [
      { qty: 7, unitPrice: 37, discountPercent: 0 },
      { qty: 11, unitPrice: 249, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.ok(Number.isInteger(totals.subtotal));
  assert.ok(Number.isInteger(totals.discount));
  assert.ok(Number.isInteger(totals.total));
  assert.equal(totals.subtotal, 7 * 37 + 11 * 249);
});

test('createInvoice accepts discountPercent on lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  });

  assert.equal(result.ok, true);
  const line = result.value.lines[0];
  assert.equal(line.discountPercent, 10);
});

test('createInvoice applies tier discount when no explicit discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  const line = result.value.lines[0];
  // C-001 is gold tier (5% discount)
  assert.equal(line.discountPercent, 5);
});

test('createInvoice accepts decimal discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 12.5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 12.5);
});

test('createInvoice reports DISCOUNT_INVALID for negative discount', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: -5 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice reports DISCOUNT_INVALID for discount > 100', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 105 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('createInvoice reports DISCOUNT_INVALID for non-numeric discount', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 'ten' }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('invoiceTotals calculates discount for single line', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 100 * 1000 = 100000
  // discount: 100000 * 10 / 100 = 10000
  // total: 100000 - 10000 = 90000
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 10000);
  assert.equal(totals.total, 90000);
});

test('invoiceTotals calculates discount for multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 10 }, // 100000 - 10000 = 90000
      { qty: 50, unitPrice: 1000, discountPercent: 20 }, // 50000 - 10000 = 40000
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 100000 + 50000 = 150000
  // discount: 10000 + 10000 = 20000
  // total: 150000 - 20000 = 130000
  assert.equal(totals.subtotal, 150000);
  assert.equal(totals.discount, 20000);
  assert.equal(totals.total, 130000);
});

test('invoiceTotals handles decimal discounts', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 12.5 }],
  };
  const totals = invoiceTotals(invoice);
